def sentence_count(text: str) -> int:
    return text.count(". ") + (1 if text.endswith(".") else 0)


def main() -> None:
    for name, code, description, _result, _prompt in ITEMS:
        count = sentence_count(description)
        if count != 6:
            raise SystemExit(f"{code} sentences={count}")
    book = openpyxl.Workbook()
    sheet = book.active
    sheet.title = "Фаза 0"
    sheet.append(["Название задачи", "Описание"])
    for cell in sheet[1]:
        cell.font = Font(bold=True)
    wrap = Alignment(wrap_text=True, vertical="top")
    for name, code, description, result, prompt in ITEMS:
        body = f"ID: {code}\n\nОписание: {description}\nРезультат задачи: {result}\nПромпт для агента: {prompt}"
        sheet.append([name, body])
        sheet.cell(sheet.max_row, 2).alignment = wrap
    sheet.column_dimensions["A"].width = 72
    sheet.column_dimensions["B"].width = 88
    book.save(OUT)
    print(f"{OUT.name} {len(ITEMS)}")


if __name__ == "__main__":
    main()
